# owner: platform
import unittest

from tests.support import data_file
from rosterkit.reader import read_roster
from rosterkit.models import Student
from rosterkit.errors import ProjectError
from rosterkit.contacts import contact_rows


def make_student(last, first, section="A", email="x@y.edu"):
    return Student("id" + last, last, first, section, email)


class ContactRowTests(unittest.TestCase):
    def test_rows_sorted_by_name(self):
        rows = contact_rows(
            [
                make_student(
                    "Varrow", "Ines", "B", "i@y.edu"
                ),
                make_student(
                    "Thistle", "Bram", "A", "b@y.edu"
                )
            ]
        )
        self.assertEqual(
            rows,
            [
                "Thistle, Bram  A  b@y.edu",
                "Varrow, Ines   B  i@y.edu"
            ]
        )

    def test_columns_line_up(self):
        rows = contact_rows(
            [
                make_student("Dunmere", "Piet", "B"),
                make_student("Halloway", "Juno", "B")
            ]
        )
        starts = {line.index("B") for line in rows}
        self.assertEqual(len(starts), 1)

    def test_roster_file_gap_is_reported(self):
        students = read_roster(data_file("roster.csv"))
        with self.assertRaises(ProjectError) as caught:
            contact_rows(students)
        message = str(caught.exception)
        self.assertIn("Quillon, Sefa", message)

    def test_missing_email_names_student(self):
        students = [
            make_student("Thistle", "Bram"),
            make_student("Varrow", "Ines", email=None)
        ]
        with self.assertRaises(ProjectError) as caught:
            contact_rows(students)
        self.assertIn("Varrow, Ines", str(caught.exception))

    def test_blank_email_is_missing(self):
        with self.assertRaises(ProjectError):
            contact_rows(
                [make_student("Thistle", "Bram", email=" ")]
            )

    def test_empty_list(self):
        with self.assertRaises(ProjectError):
            contact_rows([])
